ALTER TABLE billing_ledger_entries DROP CONSTRAINT billing_ledger_entries_entry_type_check;
ALTER TABLE billing_ledger_entries ADD CONSTRAINT billing_ledger_entries_entry_type_check CHECK(entry_type IN ('reserve','settle','refund','adjustment','purchase','redemption','referral'));
CREATE TABLE billing_products(id uuid PRIMARY KEY,code text NOT NULL UNIQUE,name text NOT NULL,description text NOT NULL DEFAULT '',units bigint NOT NULL CHECK(units>=0),price_minor bigint NOT NULL CHECK(price_minor>=0),currency char(3) NOT NULL,active boolean NOT NULL DEFAULT true,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL,updated_at timestamptz NOT NULL);
CREATE TABLE billing_promotions(id uuid PRIMARY KEY,name text NOT NULL,discount_bps integer NOT NULL CHECK(discount_bps BETWEEN 0 AND 10000),bonus_units bigint NOT NULL DEFAULT 0 CHECK(bonus_units>=0),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,active boolean NOT NULL DEFAULT true,product_id uuid REFERENCES billing_products(id) ON DELETE CASCADE,CHECK(ends_at>starts_at));
CREATE TABLE billing_redemption_codes(id uuid PRIMARY KEY,kind text NOT NULL CHECK(kind IN ('coupon','cdk')),code_hash char(64) NOT NULL UNIQUE,label text NOT NULL,discount_bps integer NOT NULL DEFAULT 0 CHECK(discount_bps BETWEEN 0 AND 10000),bonus_units bigint NOT NULL DEFAULT 0 CHECK(bonus_units>=0),max_redemptions integer NOT NULL CHECK(max_redemptions>0),redeemed_count integer NOT NULL DEFAULT 0 CHECK(redeemed_count>=0),per_user_limit integer NOT NULL DEFAULT 1 CHECK(per_user_limit>0),starts_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL,CHECK(expires_at>starts_at));
CREATE TABLE billing_code_redemptions(id uuid PRIMARY KEY,code_id uuid NOT NULL REFERENCES billing_redemption_codes(id) ON DELETE RESTRICT,user_id uuid NOT NULL REFERENCES users(id),idempotency_key text NOT NULL UNIQUE,discount_bps integer NOT NULL,bonus_units bigint NOT NULL,created_at timestamptz NOT NULL);
CREATE INDEX billing_code_redemptions_code_user_idx ON billing_code_redemptions(code_id,user_id);
CREATE TABLE billing_invite_codes(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE,code_hash char(64) NOT NULL UNIQUE,max_uses integer NOT NULL DEFAULT 100 CHECK(max_uses>0),used_count integer NOT NULL DEFAULT 0,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL,UNIQUE(owner_id));
CREATE TABLE billing_referrals(id uuid PRIMARY KEY,invite_code_id uuid NOT NULL REFERENCES billing_invite_codes(id),inviter_id uuid NOT NULL REFERENCES users(id),invitee_id uuid NOT NULL UNIQUE REFERENCES users(id),idempotency_key text NOT NULL UNIQUE,inviter_reward_units bigint NOT NULL,invitee_reward_units bigint NOT NULL,created_at timestamptz NOT NULL,CHECK(inviter_id<>invitee_id));
CREATE TABLE billing_free_grants(id uuid PRIMARY KEY,product_id uuid NOT NULL REFERENCES billing_products(id),user_id uuid NOT NULL REFERENCES users(id),units bigint NOT NULL CHECK(units>=0),created_at timestamptz NOT NULL,UNIQUE(product_id,user_id));
